def compute(vars):
    current_value = vars["v1"]
    prior_value = vars["v2"]

    if prior_value == 0:
        return None

    change = current_value - prior_value
    percentage_change = (change / prior_value) * 100

    return {
        "value": percentage_change,
        "trace": {
            "current_value": current_value,
            "prior_value": prior_value,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
